import{_ as a}from"./chunks/d0c4aff8c2a66e4c-20261015000318-wd6e841.CdNghIBn.js";import{_ as t}from"./chunks/5291123838ecf72d-20261015000318-tsue9gl.Bn59jzwj.js";import{_ as s}from"./chunks/77e56d33777be27a-20261015000318-n29j064.Crm74aKK.js";import{_ as i,o as r,c as o,a2 as l}from"./chunks/framework.D3xAlClj.js";const c="/entislng/v4/assets/4c0c969ec450c24f-20261015000318-rtg1u9q.z84oTdu-.png",n="/entislng/v4/assets/76681e12fd356c24-20261015000318-mirvuh4.BeiLiXgM.png",d="/entislng/v4/assets/8ff19889b9394584-20261015000318-vzh6aaa.DocJgWOV.png",h="/entislng/v4/assets/1834fbe7f9616fc8-20261015000318-k9zuen3.B3fqcfV1.png",p="/entislng/v4/assets/c7e5db74a896720d-20261015000318-7iddbkx.CVPwdN5c.png",_="/entislng/v4/assets/d3b1ef45b846cb01-20261015000318-ww7qcck.3bx48leI.png",V=JSON.parse('{"title":"5 数据库清理","description":"","frontmatter":{"title":"5 数据库清理","date":"2026-10-14T16:03:18.000Z","lastmod":"2026-10-14T16:03:18.000Z"},"headers":[],"relativePath":"guide/1067.md","filePath":"guide/EntisMAXIV/EntisMaxIV帮助文档/管理维护说明/系统操作/5 数据库清理.md"}'),m={name:"guide/1067.md"};function u(f,e,g,q,b,x){return r(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_5-数据库清理" tabindex="-1">5 数据库清理 <a class="header-anchor" href="#_5-数据库清理" aria-label="Permalink to &quot;5 数据库清理&quot;">​</a></h1><h1 id="_5-数据库清理-1" tabindex="-1">5 数据库清理 <a class="header-anchor" href="#_5-数据库清理-1" aria-label="Permalink to &quot;5 数据库清理&quot;">​</a></h1><p>5:数据库清理</p><h1 id="数据库清理" tabindex="-1">数据库清理 <a class="header-anchor" href="#数据库清理" aria-label="Permalink to &quot;数据库清理&quot;">​</a></h1><h1 id="" tabindex="-1">--- <a class="header-anchor" href="#" aria-label="Permalink to &quot;---&quot;">​</a></h1><h3 id="_1-功能描述" tabindex="-1">1:功能描述 <a class="header-anchor" href="#_1-功能描述" aria-label="Permalink to &quot;1:功能描述&quot;">​</a></h3><ul><li>清除指定时间内的日志数据，业务数据，报警记录等</li><li>配置数据不会被清理.</li></ul><h3 id="_2-如何开始使用" tabindex="-1">2:如何开始使用 <a class="header-anchor" href="#_2-如何开始使用" aria-label="Permalink to &quot;2:如何开始使用&quot;">​</a></h3><ul><li>依次打开菜单&quot;系统&quot;--&gt;&quot;数据库清理&quot;,如图:</li></ul><p><img src="'+c+'" alt=""> 显示清理界面<img src="'+n+'" alt=""></p><h3 id="_3-操作说明" tabindex="-1">3:操作说明 <a class="header-anchor" href="#_3-操作说明" aria-label="Permalink to &quot;3:操作说明&quot;">​</a></h3><h5 id="容量提醒" tabindex="-1"><img src="'+a+'" alt="">容量提醒 <a class="header-anchor" href="#容量提醒" aria-label="Permalink to &quot;![](assets/d0c4aff8c2a66e4c-20261015000318-wd6e841.gif)容量提醒&quot;">​</a></h5><p>界面会显示当前数据库大小和容量提醒大小,当数据库大小超过此设定值时,系统会提示进行数据库清理</p><h5 id="清理数据" tabindex="-1"><img src="'+a+'" alt="">清理数据 <a class="header-anchor" href="#清理数据" aria-label="Permalink to &quot;![](assets/d0c4aff8c2a66e4c-20261015000318-wd6e841.gif)清理数据&quot;">​</a></h5><p><img src="'+t+'" alt="">点击按钮&quot;立即删除超期数据&quot;,会显示如下确认窗体,此清理时间点计算依据为当前时间倒算指定月份的时间,例子中为12个月，在此时间点之前的数据将被清除掉.</p><p><img src="'+d+'" alt=""></p><p><img src="'+t+'" alt="">点击确认按钮以后,还将弹出密码框,输入当前操作员的密码后才会开始执行清除.</p><p><img src="'+t+'" alt="">根据清除数据量的大小不同,等待时间不一样,但一般会较长,至少在5分种以上.请耐心等待.直到弹出完成对话框</p><p><img src="'+h+'" alt=""></p><p><img src="'+t+'" alt="">表示历史数据已清理完毕,但在执行数据库清理以后,数据库的大小并没有减少,可能还会增加一点,这是因为数据虽然被标记为删除,但实际占用空间并未被释放,而且由于清理所导致的日志数据量的增加,而使得数据库的实际大小不减反增.</p><h5 id="完全清空历史数据" tabindex="-1"><img src="'+a+'" alt="">完全清空历史数据 <a class="header-anchor" href="#完全清空历史数据" aria-label="Permalink to &quot;![](assets/d0c4aff8c2a66e4c-20261015000318-wd6e841.gif)完全清空历史数据&quot;">​</a></h5><p>在一些特殊情况下，系统变得缓慢，历史数据也非常多，无法快速清除所有历史数据，此时可以通过此功能来清除所有历史数据，提高系统执行效率，在执行此功能前，强烈建议先执行备份数据库</p><h5 id="空间回收" tabindex="-1"><img src="'+a+'" alt="">空间回收 <a class="header-anchor" href="#空间回收" aria-label="Permalink to &quot;![](assets/d0c4aff8c2a66e4c-20261015000318-wd6e841.gif)空间回收&quot;">​</a></h5><p>点击按钮&quot;手动收缩&quot;,会弹出确认提示框,确认后开始执行空间回收,根据数据量不同,时间也不同,但一般会比较快,在1分钟之内,请稍等即可.</p><p><img src="'+p+'" alt=""></p><p>弹出完成对话框,表示空间回收完成.</p><p><img src="'+_+'" alt=""></p><p><img src="'+s+'" alt="">一般情况下，数据库会自动收缩并回收已删除数据的空间，但会合理保留部份空间备用，所以没有特殊情况，无需手动收缩</p><hr>',29)])])}const w=i(m,[["render",u]]);export{V as __pageData,w as default};
